use std::{fs,path::Path};use serde_json::{json,Value};
const R:&str="/home/ubuntu/src/zopro-perf-work/ready-solver246";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn median(mut a:Vec<f64>)->f64{assert_eq!(a.len(),3);a.sort_by(f64::total_cmp);a[1]}
fn main(){let r=Path::new(R);assert_eq!(read(r.join("host-remote/review.json"))["passed"],true);let raw=read(r.join("host-rows.json"));let raw=raw.as_array().unwrap();let get=|s:&str,w:u64,a:&str,b:u64|raw.iter().find(|v|v["phase"]=="latency"&&v["shape"]==s&&v["workers"]==w&&v["arm"]==a&&v["block"]==b).unwrap();let mut cells=vec![];let mut contrasts=vec![];let mut checks=vec![];for shape in["1x2","2x2","merge-54x1"]{for w in[32,96]{let mut peakref=0.;let mut peakon=0.;for arm in["REF","OFF","ON"]{let vals=|key:&str|(0..3).map(|b|get(shape,w,arm,b)[key].as_f64().unwrap()).collect::<Vec<_>>();let rss=vals("lifetime_RSS_MiB").into_iter().max_by(f64::total_cmp).unwrap();if arm=="REF"{peakref=rss}if arm=="ON"{peakon=rss}let ms=median(vals("mean_ms"));let reference=if shape=="1x2"{Some((37.,24.))}else if shape=="2x2"{Some((59.,30.))}else{None};cells.push(json!({"shape":shape,"workers":w,"arm":arm,"mean_ms_median":ms,"block_means_ms":vals("mean_ms"),"CPU_ms_per_request_median":median(vals("CPU_ms_per_request")),"lifetime_peak_RSS_MiB":rss,"M5_CPU_over_ms":reference.map(|v|v.0/ms),"M5_Metal_over_ms":reference.map(|v|v.1/ms)}));}checks.push(json!({"kind":"RSS","shape":shape,"workers":w,"passed":peakon<=peakref*1.10+8.,"ON_MiB":peakon,"REF_MiB":peakref,"limit_MiB":peakref*1.10+8.}));
let calibration=(0..3).map(|b|get(shape,w,"OFF",b)["mean_ms"].as_f64().unwrap()/get(shape,w,"REF",b)["mean_ms"].as_f64().unwrap()).collect::<Vec<_>>();let m=median(calibration.clone());checks.push(json!({"kind":"OFF_REF_calibration","shape":shape,"workers":w,"passed":(1./1.03..=1.03).contains(&m),"median_ratio":m,"blocks":calibration}));
for control in["REF","OFF"]{let ratios=(0..3).map(|b|get(shape,w,"ON",b)["mean_ms"].as_f64().unwrap()/get(shape,w,control,b)["mean_ms"].as_f64().unwrap()).collect::<Vec<_>>();let cpu=(0..3).map(|b|get(shape,w,"ON",b)["CPU_ms_per_request"].as_f64().unwrap()/get(shape,w,control,b)["CPU_ms_per_request"].as_f64().unwrap()).collect::<Vec<_>>();let m=median(ratios.clone());let c=median(cpu.clone());contrasts.push(json!({"shape":shape,"workers":w,"control":control,"latency_median_ratio":m,"latency_blocks":ratios,"CPU_median_ratio":c,"CPU_blocks":cpu}));if shape=="1x2"&&w==96{for(b,v)in ratios.iter().enumerate(){checks.push(json!({"kind":"primary96_backing_gain","control":control,"backing":b,"passed":*v<1.,"ratio":v}));}checks.push(json!({"kind":"primary96_CPU","control":control,"passed":c<=1.,"median_ratio":c}));}else{checks.push(json!({"kind":"latency_nonregression","shape":shape,"workers":w,"control":control,"passed":m<=1.03,"median_ratio":m}));}}
}}assert_eq!(checks.len(),30);let passed=checks.iter().all(|v|v["passed"]==true);let result=json!({"directional_screen_passed":passed,"not_adoption_qualification":true,"cells":cells,"contrasts":contrasts,"checks":checks,"all8_CPU10x_goal_achieved":false,"canonical_count":64301});let p=r.join("decision.json");assert!(!p.exists());fs::write(p,serde_json::to_vec_pretty(&result).unwrap()).unwrap();println!("screen_passed={passed}");for v in result["cells"].as_array().unwrap(){println!("{} {} {} {:.6}ms",v["shape"],v["workers"],v["arm"],v["mean_ms_median"].as_f64().unwrap());}for v in result["checks"].as_array().unwrap().iter().filter(|v|v["passed"]==false){println!("FAIL {v}");}}
